import React, { useContext, useState, useRef } from "react";
import noteContext from "../context/notes/noteContext";

const AddNote = (props) => {
  const context = useContext(noteContext);
  const { addNote } = context;
  const [note, setNote] = useState({ 
    title: "", 
    description: "", 
    tag: "",
    attachments: [],
    images: [],
    todoItems: []
  });
  const [isRichTextMode, setIsRichTextMode] = useState(false);
  const descriptionRef = useRef(null);

  const handleClick = async (e) => {
    e.preventDefault();

    try {
      const success = await addNote(
        note.title, 
        note.description, 
        note.tag,
        note.attachments,
        note.images,
        note.todoItems
      );

      if (success !== false) {
        setNote({ 
          title: "", 
          description: "", 
          tag: "",
          attachments: [],
          images: [],
          todoItems: []
        });
        // Clear rich text editor if in rich text mode
        if (isRichTextMode && descriptionRef.current) {
          descriptionRef.current.innerHTML = '';
        }
        props.showAlert("Added Successfully", "success");
      } else {
        props.showAlert("Failed to add note", "danger");
      }
    } catch (error) {
      console.error('Error in handleClick:', error);
      props.showAlert("Failed to add note", "danger");
    }
  };

  const onChange = (e) => {
    setNote({ ...note, [e.target.name]: e.target.value });
  };

  // Rich Text Editor Functions
  const formatText = (command, value = null) => {
    document.execCommand(command, false, value);
    descriptionRef.current.focus();
  };

  const handleRichTextChange = () => {
    if (descriptionRef.current) {
      setNote({ ...note, description: descriptionRef.current.innerHTML });
    }
  };

  const toggleRichTextMode = () => {
    setIsRichTextMode(!isRichTextMode);
    if (!isRichTextMode) {
      // Switching to rich text mode
      setTimeout(() => {
        if (descriptionRef.current) {
          descriptionRef.current.innerHTML = note.description;
        }
      }, 0);
    } else {
      // Switching to plain text mode
      if (descriptionRef.current) {
        setNote({ ...note, description: descriptionRef.current.textContent });
      }
    }
  };

  // Todo Items Functions
  const addTodoItem = () => {
    setNote({
      ...note,
      todoItems: [...note.todoItems, { text: "", completed: false }]
    });
  };

  const updateTodoItem = (index, field, value) => {
    const updatedTodos = [...note.todoItems];
    updatedTodos[index] = { ...updatedTodos[index], [field]: value };
    setNote({ ...note, todoItems: updatedTodos });
  };

  const removeTodoItem = (index) => {
    const updatedTodos = note.todoItems.filter((_, i) => i !== index);
    setNote({ ...note, todoItems: updatedTodos });
  };

  // File Upload Functions
  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        setNote(prev => ({
          ...prev,
          images: [...prev.images, {
            name: file.name,
            url: event.target.result,
            size: file.size
          }]
        }));
      };
      reader.readAsDataURL(file);
    });
  };

  const removeImage = (index) => {
    const updatedImages = note.images.filter((_, i) => i !== index);
    setNote({ ...note, images: updatedImages });
  };

  const handleFileUpload = (e) => {
    const files = Array.from(e.target.files);
    files.forEach(file => {
      setNote(prev => ({
        ...prev,
        attachments: [...prev.attachments, {
          name: file.name,
          size: file.size,
          type: file.type
        }]
      }));
    });
  };

  const removeAttachment = (index) => {
    const updatedAttachments = note.attachments.filter((_, i) => i !== index);
    setNote({ ...note, attachments: updatedAttachments });
  };

  return (
    <div className="container my-4">
      <div className="card">
        <div className="card-header">
          <h2 className="mb-0">Add a Note</h2>
        </div>
        <div className="card-body">
          <form>
            <div className="mb-3">
              <label htmlFor="title" className="form-label">
                <i className="fas fa-heading me-2"></i>Title
              </label>
              <input
                type="text"
                className="form-control"
                id="title"
                name="title"
                onChange={onChange}
                minLength={5}
                required
                value={note.title}
                placeholder="Enter note title..."
              />
            </div>

            <div className="mb-3">
              <div className="d-flex justify-content-between align-items-center mb-2">
                <label htmlFor="description" className="form-label">
                  <i className="fas fa-align-left me-2"></i>Description
                </label>
                <div className="form-check">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id="richTextToggle"
                    checked={isRichTextMode}
                    onChange={toggleRichTextMode}
                  />
                  <label className="form-check-label" htmlFor="richTextToggle">
                    Rich Text Editor
                  </label>
                </div>
              </div>

              {isRichTextMode && (
                <div className="mb-2">
                  <div className="btn-toolbar" role="toolbar">
                    <div className="btn-group me-2" role="group">
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('bold')}
                        title="Bold"
                      >
                        <i className="fas fa-bold"></i>
                      </button>
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('italic')}
                        title="Italic"
                      >
                        <i className="fas fa-italic"></i>
                      </button>
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('underline')}
                        title="Underline"
                      >
                        <i className="fas fa-underline"></i>
                      </button>
                    </div>
                    <div className="btn-group me-2" role="group">
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('insertUnorderedList')}
                        title="Bullet List"
                      >
                        <i className="fas fa-list-ul"></i>
                      </button>
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('insertOrderedList')}
                        title="Numbered List"
                      >
                        <i className="fas fa-list-ol"></i>
                      </button>
                    </div>
                    <div className="btn-group me-2" role="group">
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('justifyLeft')}
                        title="Align Left"
                      >
                        <i className="fas fa-align-left"></i>
                      </button>
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('justifyCenter')}
                        title="Align Center"
                      >
                        <i className="fas fa-align-center"></i>
                      </button>
                      <button
                        type="button"
                        className="btn btn-outline-secondary btn-sm"
                        onClick={() => formatText('justifyRight')}
                        title="Align Right"
                      >
                        <i className="fas fa-align-right"></i>
                      </button>
                    </div>
                  </div>
                </div>
              )}

              {isRichTextMode ? (
                <div
                  ref={descriptionRef}
                  className="form-control"
                  contentEditable
                  onInput={handleRichTextChange}
                  style={{ minHeight: '120px' }}
                  data-placeholder="Enter your note content here..."
                />
              ) : (
                <textarea
                  className="form-control"
                  id="description"
                  name="description"
                  onChange={onChange}
                  rows="5"
                  minLength={5}
                  required
                  value={note.description}
                  placeholder="Enter your note content here..."
                />
              )}
            </div>

            <div className="mb-3">
              <label htmlFor="tag" className="form-label">
                <i className="fas fa-tags me-2"></i>Tags
              </label>
              <input
                type="text"
                className="form-control"
                id="tag"
                name="tag"
                value={note.tag}
                onChange={onChange}
                placeholder="work, personal, important (comma separated)"
              />
              <div className="form-text">Separate multiple tags with commas</div>
            </div>

            {/* Todo Items Section */}
            <div className="mb-3">
              <label className="form-label">
                <i className="fas fa-tasks me-2"></i>Todo Items
              </label>
              {note.todoItems.map((todo, index) => (
                <div key={index} className="d-flex mb-2">
                  <div className="form-check me-2">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      checked={todo.completed}
                      onChange={(e) => updateTodoItem(index, 'completed', e.target.checked)}
                    />
                  </div>
                  <input
                    type="text"
                    className="form-control me-2"
                    value={todo.text}
                    onChange={(e) => updateTodoItem(index, 'text', e.target.value)}
                    placeholder="Todo item"
                  />
                  <button
                    type="button"
                    className="btn btn-outline-danger btn-sm"
                    onClick={() => removeTodoItem(index)}
                  >
                    <i className="fas fa-trash"></i>
                  </button>
                </div>
              ))}
              <button
                type="button"
                className="btn btn-outline-primary btn-sm"
                onClick={addTodoItem}
              >
                <i className="fas fa-plus me-1"></i>Add Todo Item
              </button>
            </div>

            {/* Image Upload Section */}
            <div className="mb-3">
              <label htmlFor="imageUpload" className="form-label">
                <i className="fas fa-image me-2"></i>Images
              </label>
              <input
                type="file"
                className="form-control"
                id="imageUpload"
                multiple
                accept="image/*"
                onChange={handleImageUpload}
              />
              {note.images.length > 0 && (
                <div className="mt-2">
                  <small className="text-muted">Uploaded Images:</small>
                  {note.images.map((image, index) => (
                    <div key={index} className="d-flex align-items-center mt-1">
                      <img 
                        src={image.url} 
                        alt={image.name} 
                        style={{ width: '50px', height: '50px', objectFit: 'cover' }} 
                        className="me-2 rounded"
                      />
                      <span className="me-2">{image.name}</span>
                      <button
                        type="button"
                        className="btn btn-outline-danger btn-sm"
                        onClick={() => removeImage(index)}
                      >
                        <i className="fas fa-times"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* File Attachments Section */}
            <div className="mb-3">
              <label htmlFor="fileUpload" className="form-label">
                <i className="fas fa-paperclip me-2"></i>File Attachments
              </label>
              <input
                type="file"
                className="form-control"
                id="fileUpload"
                multiple
                onChange={handleFileUpload}
              />
              {note.attachments.length > 0 && (
                <div className="mt-2">
                  <small className="text-muted">Attached Files:</small>
                  {note.attachments.map((file, index) => (
                    <div key={index} className="d-flex align-items-center mt-1">
                      <i className="fas fa-file me-2"></i>
                      <span className="me-2">{file.name} ({Math.round(file.size / 1024)} KB)</span>
                      <button
                        type="button"
                        className="btn btn-outline-danger btn-sm"
                        onClick={() => removeAttachment(index)}
                      >
                        <i className="fas fa-times"></i>
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="d-grid">
              <button
                disabled={note.title.length < 5 || note.description.length < 5}
                type="submit"
                className="btn btn-primary btn-lg"
                onClick={handleClick}
              >
                <i className="fas fa-save me-2"></i>Add Note
              </button>
            </div>
          </form>
        </div>
      </div>

      <style jsx>{`
        .form-control[contenteditable]:empty:before {
          content: attr(data-placeholder);
          color: #6c757d;
          font-style: italic;
        }
        .btn-toolbar {
          background-color: #f8f9fa;
          padding: 8px;
          border-radius: 0.375rem;
          border: 1px solid #dee2e6;
        }
      `}</style>
    </div>
  );
};

export default AddNote;
